function MULTIPLY(x = (d_x, c_x), y = (d_y, c_y)):
    raw <- zero vector of length |c_x| + |c_y| - 1
    for i in 0 .. |c_x| - 1:
        if c_x[i] = 0: continue
        for j in 0 .. |c_y| - 1:
            raw[i + j] <- raw[i + j] + c_x[i] * c_y[j]
    d <- d_x + d_y
    reliable_top <- min(top(x) + d_y, top(y) + d_x)
    return (d, raw[0 .. reliable_top - d])

function PRODUCT(f_1, ..., f_m):
    acc <- f_1
    for i in 2 .. m: acc <- MULTIPLY(acc, f_i)
    return acc

function POLE_ORDER(x = (d, c)):
    for j in 0 .. |c| - 1:
        if c[j] != 0: return d + j
    return UNDETERMINED

function SHIFT(x = (d, c), k):  return (d + k, c)

postcondition: POLE_ORDER(PRODUCT(f_1..f_m)) = -m whenever each f_i is
               normalized, and POLE_ORDER(SHIFT(x, k)) = POLE_ORDER(x) + k.

