function BLIND(x, u):
    require offset(u) = 0 and u_0 != 0        # u is a unit power series
    return MULTIPLY(x, u)                     # ord unchanged

function MASK(x, y):
    require ord(y) > ord(x)                   # strictly less singular
    return ADD(x, y)                          # ord unchanged

function PIPELINE(x, u, y, k):
    return MASK(SHIFT(BLIND(x, u), k), y)      # ord = ord(x) + k

function LEAK(z):    return POLE_ORDER(z)

function UNMASKING_SHIFT(x):
    return -POLE_ORDER(x)                     # the unique k with ord(q^k x) = 0

guarantee: for every admissible (u, y, k), LEAK(PIPELINE(x,u,y,k)) = ord(x) + k,
           and k* = -ord(x) is the unique solution of LEAK(SHIFT(x,k)) = 0.

