"""Algorithm C: the blinding / masking / unmasking pipeline for the pole-order leak.

Given a Laurent series x, an invertible power series u (nonzero constant term), an additive
mask y strictly less singular than x, and a monomial shift q^k, the transformed transcript

        z = q^k * (u * x) + y

satisfies ord(z) = ord(x) + k exactly.  Hence an observer of z learns ord(x) + k and nothing
more from valuation queries, and the unique shift returning the series to order zero is
k* = -ord(x).  Each step costs one convolution, O(N log N) at worst; leak extraction is O(N).
"""

from __future__ import annotations

from fractions import Fraction
from typing import List, Optional, Sequence, Tuple

LaurentSeries = Tuple[int, List[Fraction]]


def _mk(offset: int, coeffs: Sequence[object]) -> LaurentSeries:
    return offset, [Fraction(c) for c in coeffs]  # type: ignore[arg-type]


def _top(x: LaurentSeries) -> int:
    return x[0] + len(x[1]) - 1


def _mul(x: LaurentSeries, y: LaurentSeries) -> LaurentSeries:
    dx, cx = x
    dy, cy = y
    raw: List[Fraction] = [Fraction(0)] * (len(cx) + len(cy) - 1)
    for i, a in enumerate(cx):
        if a == 0:
            continue
        for j, b in enumerate(cy):
            raw[i + j] += a * b
    offset = dx + dy
    keep = min(_top(x) + dy, _top(y) + dx) - offset + 1
    return offset, raw[: max(keep, 0)]


def _add(x: LaurentSeries, y: LaurentSeries) -> LaurentSeries:
    lo = min(x[0], y[0])
    hi = min(_top(x), _top(y))

    def at(s: LaurentSeries, d: int) -> Fraction:
        return s[1][d - s[0]] if s[0] <= d <= _top(s) else Fraction(0)

    return lo, [at(x, d) + at(y, d) for d in range(lo, hi + 1)]


def leak(x: LaurentSeries) -> Optional[int]:
    """The pole leak lambda(x) = ord(x)."""
    offset, coeffs = x
    for j, c in enumerate(coeffs):
        if c != 0:
            return offset + j
    return None


def blind(x: LaurentSeries, unit: LaurentSeries) -> LaurentSeries:
    """Multiplicative blinding by a power series with nonzero constant term."""
    if unit[0] != 0 or unit[1][0] == 0:
        raise ValueError("the blinding factor must be a power series with nonzero constant term")
    return _mul(x, unit)


def mask(x: LaurentSeries, noise: LaurentSeries) -> LaurentSeries:
    """Additive masking by a strictly less singular series."""
    lx, ln = leak(x), leak(noise)
    if lx is None:
        raise ValueError("x vanishes in its window")
    if ln is not None and ln <= lx:
        raise ValueError("the additive mask must have order strictly greater than ord(x)")
    return _add(x, noise)


def shift(x: LaurentSeries, k: int) -> LaurentSeries:
    """Monomial shift by q^k: moves the leak by exactly k."""
    return x[0] + k, x[1]


def pipeline(
    x: LaurentSeries, unit: LaurentSeries, noise: LaurentSeries, k: int
) -> LaurentSeries:
    """z = q^k (u x) + y, the full transcript seen by an observer."""
    return mask(shift(blind(x, unit), k), noise)


def unmasking_shift(x: LaurentSeries) -> int:
    """The unique k* with ord(q^{k*} x) = 0."""
    lx = leak(x)
    if lx is None:
        raise ValueError("x vanishes in its window")
    return -lx


def demo() -> None:
    # A product of three normalized series has order -3.
    def normalized(tail: Sequence[int]) -> LaurentSeries:
        return _mk(-1, [1, *tail])

    x = normalized([0, 196884, 21493760, 864299970])
    for tail in ([0, 4372, 96256, 1240002], [0, 783, 8672, 65367]):
        x = _mul(x, normalized(tail))

    unit = _mk(0, [7, -3, 11, 0, 5])
    for k in (0, 3, 5):
        noise = _mk(-2 + k, [999, -17, 4])  # strictly less singular than q^k (u x)
        z = pipeline(x, unit, noise, k)
        print(f"  shift k = {k}: leak(z) = {leak(z)}  (= ord(x) + k = {leak(x)} + {k})")
        assert leak(z) == leak(x) + k
    print(f"  unique unmasking shift for x: k* = {unmasking_shift(x)}")


if __name__ == "__main__":
    demo()
